sys_script_include.script:
var EnrollmentValidator = Class.create();
EnrollmentValidator.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    hasExistingEnrollment: function() {
        var userId = this.getParameter('sysparm_user_id');
        var scheduleId = this.getParameter('sysparm_schedule_id');

        var gr = new GlideRecord('x_1151896_sharkt_0_enrollments');
        gr.addQuery('opened_by', userId);
        gr.addQuery('training_schedule', scheduleId);
        gr.query();

        return gr.hasNext() ? 'true' : 'false';
    },


    type: 'EnrollmentValidator'
});
